// Express.js & MongoDB JWT Authentication Middleware
import jwt from "jsonwebtoken";
import { UserRole } from "../models/user.model.js";

export const requireRole = (allowedRoles: UserRole[]) => {
  return async (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      const token = req.headers.authorization?.split(" ")[1];
      if (!token) return res.status(401).json({ error: "Access token required" });

      const decoded = jwt.verify(token, process.env.JWT_SECRET!) as TokenPayload;
      if (!allowedRoles.includes(decoded.role)) {
        return res.status(403).json({ error: "Permission denied for this operation" });
      }

      req.user = decoded;
      next();
    } catch (err) {
      return res.status(401).json({ error: "Invalid or expired token" });
    }
  };
};

// Automated Deadline Notification Scheduler
cron.schedule("0 9 * * *", async () => {
  const pendingTasks = await Task.find({
    status: { $ne: "COMPLETED" },
    dueDate: { $lte: new Date(Date.now() + 24 * 60 * 60 * 1000) }
  }).populate("assignee");

  await sendNotificationBatch(pendingTasks);
});
